    [2204] = "Добудьте источник энергии из самого мощного волшебного создания, которое найдете в Ульдамане и доставьте его Талвашу де Кисселю в Стальгорн.",
    [2240] = "Прочитайте журнал Бейлога, исследуйте, потайной чертог и потом доложите об увиденном геологу Грозовой Вершине.",
    [2278] = "Поговорите с каменным Стражем и запомните все, что он передаст вам. Когда он закончит свой пересказ событий древности, активируйте диски Норганнона.",
    [2279] = "Отнесите миниатюрную копию дисков Норганнона в Лигу Исследователей в Стальгорне.",
    [2280] = "Отнесите миниатюрную копию дисков Норганнона кому-то из мудрецов с Громового Утеса.",
    [2283] = "Найдите на раскопках Ульдамана драгоценное ожерелье (возможно, поврежденное) и принесите его в Оргриммар Драну Дрофферсу.",
    [2284] = "Разыщите ключ к местонахождению самоцветов в глубинах Ульдамана.",
    [2318] = "Найдите кого-нибудь, кто сможет перевести для вас дневник паладина. Ближайший к вам такой умелец, скорее всего, найдется в Каргате, форпосте в Бесплодных Землях.",
    [2338] = "Одолжите ожерелье Джаркалу. Взамен он переведет дневник.",
    [2339] = "Добудьте все три самоцвета и источник энергии для ожерелья из Ульдамана и принесите их Джаркалу Замшелому Клыку в Каргат. Джаркал считает, что источник энергии можно найти у самой сильной твари в Ульдамане.$B$BИз дневника следует...$B* Рубин спрятан на огражденной завалами территории Кузни Теней.$B*Топаз спрятан в урне на территорях троггов под боком у дворфов Альянса.$B*Сапфир забрал Гримлок, старейшина троггов.",
    [2340] = "Доставьте ожерелье и драгоценности Драну Дрофферсу в Оргриммар.",
    [2341] = "Навестите Джаркала Замшелого Клыка в Каргате.",
    [2342] = "Принесите Патрику Гарретту в Подгород фамильное сокровище из сундука в Южном зале Ульдамана.",
    [2359] = "Добудьте ключ Башни Братства Справедливости, проберитесь в башню и выясните, каково содержимое сундука из Сумеречного леса. Отнесите найденные вещи Матиасу Шоу в Штормград. Почитайте дневник Кеарнен, чтобы больше узнать о башне.",
    [2360] = "Найдите посланницу Кеарнен в Западном Крае и поговорите с ней.",
    [2361] = "Я с великой радостью вручаю тебе это ожерелье, могучий |3-6(Жрец). Ты оказал мне неоценимую услугу, и я благодарен тебе за это. Носи же его с гордостью и не забывай при этом все время упоминать о том, кто сделал его для тебя!$B$BДа, если еще добавишь, что на ожерелье нет проклятия, это будет великолепно.",
    [2398] = "Найдите Бейлога в Ульдамане.",
    [2418] = "Принесите 8 дентриевых камней Силы и 8 энелиевых камней Силы Ригглфаззу в Бесплодные земли.",
    [2439] = "Отнесите наградной сертификат Дините Каменной Мантии в хранилище Стальгорна.",
    [2440] = "Отнесите наградной сертификат Бене Заиндевевшее Копыто в Громовой Утес.",
    [2458] = "Отыщите башню Торговой компании к северу от Нефтяного болота и вступите в контакт с тайным агентом Изувеченной Длани, надсмотрщиком Физзулом.$B$BВозле башни выстрелите из сигнального ружья ДВА раза, потом подойдите к надсмотрщику Физзулу и продемонстрируйте приветствие Изувеченной Длани (команда /честь).$B$BВсе нужно делать строго по порядку – Физзул убивает всех, кто кажется ему подозрительным.",
    [2460] = "Повторите приветствие Раздробленной Руки вслед за Шентулом.",
    [2478] = "Украдите ключ от башни у штейгера Силиксиза, убейте двух мертвяков-мутантов Торговой компании, двух патрульных Торговой компании и двух смотрителей Торговой компании.$B$BЛиквидируйте старшего мастера Галливикса, взломайте замок на его ящике и украдите запас измененной смеси Занзила. Отнесите запас смеси и голову Галливикса Шентулу в Оргриммар и получите следующие указания.",
    [2479] = "Пойдите на Мельницу Таррен в предгорьях Хилсбрада и доставьте образчик смеси Занзила Сержу Хинотту.$B$BСядьте на дирижабль, идущий до Подгорода, и летите вдоль дороги на юг, через Серебряный бор в сторону Хилсбрада. Следите за знаками.",
    [2480] = "Дождитесь, пока Серж Хинотт доделает лекарство.",
    [2607] = "Поговорите с Доком Миксиль-Пиксилем в подвале казарм.",
    [2608] = "Лягте на землю (действие /lay) для осмотра Доком Миксиль-Пиксилем – он не сможет подобрать лекарство, пока не найдет причину болезни.",
    [2609] = "Принесите Доку Миксиль-Пиксилю один букетик простых полевых цветов, одну освинцованную колбу, одну бронзовую трубку и одну катушку светлого зеленовато-желтого шелка. Чтотит, знаете ли, сам собой не проходит.",
    [2621] = "Поговорите с командиром разведотряда Руагом в Каменоре.",
    [2622] = "Поговорите с Бенгором.",
    [2623] = "Заберите приказы Вождя и верните их павшему герою Орды.",
    [2681] = "Освободите девять Слуг Разелиха, трех Слуг Севины, трех Слуг Аллистария и трех Слуг Грола. Когда ваша задача будет выполнена, возвращайтесь к павшему герою. Вы должны оставаться поблизости от камней, иначе процесс не будет завершен.",
    [2701] = "Откройте шкатулку и возьмите награду.",
    [2702] = "Поговорите с капралом Тундом Треснувшее Копыто.",
    [2721] = "Узнайте, что стало с лейтенантом Киритом.",
    [2743] = "Вернитесь к павшему герою Орды со своими находками.",
    [2744] = "Поговорите в Азшаре с Лорамусом Многоногом.",
    [2745] = "Поговорите с Тирионом в Крепости Штормграда.",
    [2746] = "Принесите Тириону в Штормград 3 отреза шелка и 2 свежих яблока Клары.",
    [2768] = "Принесите изыскательский cтержень главному инженеру Чепухастеру в Прибамбасск.",
    [2770] = "Принесите искрящую чешую Газ'риллы Виззлу Медноштифу на Мерцающую равнину.",
    [2783] = "Поговорите с павшим героем Орды на границе Выжженных земель и болот.",
    [2784] = "Послушайте, как павший герой Орды рассказывает свою историю.",
    [2801] = "Послушайте, как павший герой Орды рассказывает свою историю.",
    [2846] = "Принесите Тиару Глубин Табете в Пыльную Трясину.",
    [2861] = "Поговорите с Табетой в Пылевых топях.",
    [2864] = "Поговорите с Тран'реком в Прибамбасске.",
    [2865] = "Принести 5 целых панцирей скарабея Тран'реку в Прибамбасск.",
    [2936] = "Прочитайте надписи на табличке Теки, узнайте имя паучьей богини, которой поклоняются тролли Сухокожих, а потом возвращайтесь к мастеру Гадрину.",
    [2983] = "Найдите в Степях Кранала Фисса.",
    [2984] = "Найдите в Степях Кранала Фисса.",
    [2985] = "Отыщите в Степях Ислен Заклинательницу Воды.",
    [2986] = "Отыщите в Степях Ислен Заклинательницу Воды.",
    [2991] = "Отнесите медальон Некрума Тадиусу Мрачной Тени в Выжженные земли.",
    [3001] = "Поговорите со Страхадом Фарсаном в Кабестане.",
    [3042] = "Принесите 20 фиалов с Тролльим месивом.",
    [3141] = "Послушайте, как Лорамус Многоног рассказывает свою историю.",
    [3369] = "Принесите осколок кошмара Хамуулу Руническому Тотему на Вершине Старейшин.",
    [3370] = "Принесите осколок кошмара Матренгилу Медвежьей Лапе в Дарнасс.",
    [3373] = "Поместите сущность Эраникуса в купель сущности в его логове в затонувшем храме.",
    [3380] = "Найдите Марвона Клепальщика в Танарисе.",
    [3446] = "Найдите алтарь Хаккара в затонувшем храме на Болоте Печали.",
    [3447] = "Отправляйтесь в затонувший храм и узнайте, что скрывается в круге статуй.",
    [3504] = "Отнесите запечатанное письмо Аг'тору Кровопалу в Азшару.",
    [3505] = "Убейте 10 эльфов крови-землемеров и 10 эльфов крови-геодезистов, потом разыщите лагерь волхва Римтори. В лагере найдите что-нибудь важное для мага, из-за чего она могла бы ринуться в бой.",
    [3508] = "Подождите, пока Лорамус завершит заклинание просветления.",
    [3509] = "Поговорите в Азшаре с лордом Арккоросом. Начните поиски у кромки воды, чтобы найти Храм Арккоран.",
    [3510] = "Убейте Хетайру и принесите окровавленную голову Хетайры, разбитую голову Хетайры и покрытую синяками голову Хетайры лорду Аккоросу.",
    [3511] = "Отнесите состав для закалки Лорамусу Многоногу.",
    [3520] = "Поймайте души трех крикунов из Фераласа и возвращайтесь к Йе'кинье в Порт Картеля.",
    [3527] = "Принесите первую и вторую таблички Мошару Йе'кинье в Танарис.",
    [3528] = "Отнесите заполненное яйцо Хаккара Йе'кинье в Танарис.",
    [3602] = "Найдите в южной Азшаре двадцать кристаллов азшарита. Вы можете использовать Гончих Скверны, которые помогут вам \"вынюхивать\" местонахождение хорошо сокрытых залежей.$B$BКогда задача будет завершена, возвращайтесь к Лорамусу Многоногу.",
    [3621] = "Отнести груз Гальвану Древнему в Тернистую долину.",
    [3625] = "Подождите, пока Гальван закончит отковывать оружие.",
    [3626] = "Вернитесь к Павшему герою Орды.",
    [3627] = "Убейте Грола Разрушителя, леди Севину и верховного мага Аллистария. С их трупов заберите Амулет Грола, Амулет Севины и Амулет Аллистария.$B$BПомните о том, что нужно использовать зачарованное азшаритовое оружие, отравленное Скверной, чтобы ослабить троицу! Их нельзя убить иначе – но используйте оружие разумно...",
    [3628] = "Уничтожьте Разелиха Осквернителя и вернитесь к Павшему герою Орды с Отрубленным Рогом Осквернителя. Вам также понадобится вернуть Оберег Осквернителя, чтобы Павший герой мог уничтожить его, дабы оберег не попал к тому, кто использует его во зло.",
    [3631] = "Поговорите в Кабестане со Страхадом Фарсаном.",
    [3701] = "Пойдите в руины Тауриссана в Пылающих степях и добудьте информацию из таурисанских реликвий. Вернитесь к королевскому историку Аркессону.",
    [3702] = "Узнайте от королевского историка Аркессона историю Тауриссана.",
    [3783] = "Соберите 10 толстых кусков меха йети для Юми Румпельшникер из Круговзора.",
    [3801] = "Чтобы получить ключ от города, поговорите с Франклорном Искусником.",
    [3802] = "Убейте Точеня Темностроя и добудьте великий молот, Железный Друг. Отнесите Железного Друга в святилище Тауриссана и вложите его в руки статуи Франклорна Искусника.",
    [3844] = "Осмотритесь и попытайтесь выяснить, кому мог бы принадлежать разбитый плот.",
    [3845] = "Изучите найденное в сумке и верните владельцу.",
    [3903] = "Поговорите с Милли Осворт.",
    [3904] = "Принесите 8 корзин с виноградом Милли Осворт в Аббатство Североземья.",
    [3907] = "Ступайте в глубины Черной горы и выследите лорда Опалителя. Убейте его и принесите Громосерду все, что может дать какую-то информацию.",
    [3908] = "Отнесите меч Линкена Донове Снегоноре.",
    [3909] = "Найдите Грегана Пивоплюя на севере Фераласа. Выясните у него, как получить эликсир Видере, и вернитесь к Донове Снегоноре.",
    [3912] = "Отправляйтесь на кладбище на окраине Прибамбасска и выпейте там эликсир Видере. Далее, следуя инструкциям Доновы, найдите Гаэриана.",
    [3913] = "Воскресните, найдите могильный камень, о котором говорил Гаэриан.",
    [3914] = "Доставьте превосходный меч Линкена Линкену в Кратер Ун'Горо.",
    [3941] = "Найдите Джей Ди Колли в Укрытии Маршалла.",
    [3942] = "Найдите Эридану Грусть Ветра на юге Оскверненного леса.",
    [3961] = "Отнесите серебряный тотем Аквамонтоса Линкену в Укрытие Маршалла.",
    [3962] = "Отправляйтесь к Вулкану Огненного Венца, к югу от Укрытия Маршалла.$B$BНайдите Яропламеня и разрушьте его защитную ауру с помощью тотема. Когда дух будет сражен, заберите из пещеры Золотое пламя.",
    [3981] = "Найдите командира Гор'шака в Глубинах Черной горы.$B$BСудя по рисунку в записке, искать следует в темнице где-то вроде того.",
    [3982] = "Защитите Горшака.",
    [4001] = "Поговорите с дворфом по имени Каран Могучий Молот и соберите информацию о похищении принцессы Мойры Бронзобород. Передайте информацию Траллу в Оргриммар.$B$BКарана держат в темнице напротив.",
    [4002] = "Поговорите с Траллом.",
    [4003] = "Убейте императора Даграна Тауриссана и освободите принцессу Мойру Бронзобород от его черного заклятия.",
    [4004] = "Вернитесь к Траллу.",
    [4005] = "Отнесите книгу Аквора, серебристые когти и сердце Железнолесья в Танарис.$B$BВоспользуйтесь книгой для призыва Аквамонтоса.$B$BПо получении тотема, отнести его Джей Ди Колли в Укрытие Маршалла.",
    [4024] = "Отправьтесь в глубины Черной горы и убейте Бейл'Гора.$B$BИзвестно лишь то, что великан живет в глубинах. Воспользуйтесь измененной сброшенной шкурой черного дракона и возьмите из останков Бейл'Гора сущность Огня.$B$BОтнесите пойманную сущность Огня Цирусу Раскаивателю.",
    [4063] = "Найдите и убейте повелителя големов Аргелмаха. Принесите его голову Лотвилу. Также соберите 10 невредимых ядер стихий с беспощадных големов и созданий-завоевателей, охраняющих Аргелмаха. Информация передана посредством телепатии.",
    [4081] = "Отправляйтесь в Глубины Черной горы и уничтожьте подлых агрессоров!$B$BПо приказу полководца Клинозуба уничтожьте 15 охранников, 10 надсмотрщиков и 5 пехотинцев из клана Ярости Горна. Вернитесь сразу по выполнении задания.",
    [4082] = "Отправляйтесь в Глубины Черной горы и уничтожьте подлых агрессоров!$B$BПо приказу полководца Клинозуба уничтожьте 10 медиков, 10 солдат и 10 офицеров из клана Ярости Горна. Вернитесь сразу по выполнении задания.",
    [4083] = "Призрачный кубок парит в воздухе, медленно поднимаясь и опускаясь... как будто следуя ритмам биения умирающего сердца.",
    [4084] = "Добудьте 11 серебристых когтей и 1 сердце Железнолесья для Эриданы Грусти Ветра.",
    [4121] = "Отконвоируйте пленника, Грарка Лорктуба, через Пылающие степи и Черную гору к Тлеющему ущелью.$B$BЛекслорт что-то говорил насчет того, что по другую сторону будут ждать его ребята, которые уведут Грарка в тюрьму.$B$BТакже отдайте Лекслорту ториевые оковы.",
    [4122] = "Отправьтесь в Пылающие степи и найдите Грарка Лоркруба. Лекслорт упоминал, что в последний раз предателя видели в крепости Черной горы.$B$BПо обнаружении Грарка Лоркруба закуйте его в ториевые оковы и затем доставьте его от Черной горы к Тлеющему ущелью, Лекслорт и его подчиненные займутся допросом преступника.",
    [4123] = "Принесите сердце горы Максворту Суперблеску в Пылающие степи.",
    [4124] = "Поговорите с Гинро Пылающим Очагом в Крепости Оперенной Луны.",
    [4125] = "Отыщите лодку курьера, которая должна находиться где-то на побережье Фераласа.",
    [4126] = "Найдите украденный рецепт громоварского и верните его Рагнару Громовару в Каранос.",
    [4127] = "Вернитесь в Крепость Оперенной Луны и покажите Гинро Пылающему Очагу выброшенный нож, который вы нашли.",
    [4128] = "Переговорите с Рагнаром Громоваром.",
    [4129] = "Отнесите выброшенный нож к друиду по имени Квинтис Ночной Костер в Крепости Оперенной Луны.",
    [4130] = "Поговорите с Гинро Пылающим Очагом в Крепости Оперенной Луны.",
    [4131] = "Обыщите лагеря Древолапов в южном Фераласе в поисках вещей курьера либо самого курьера.",
    [4132] = "Отправляйтесь в Глубины Черной горы и убейте генерала Кузню Гнева. Вернитесь к полководцу Клинозубу по выполнении задания.",
    [4133] = "Переговорите с тенемагом Вивиан Лаграв в Каргате.",
    [4134] = "Принесите рецепт громоварского светлого Вивиан Лягроб в Каргат.",
    [4135] = "Продолжайте поиски Раскала (или его останков) в Гудящей Бездне. Согласно записке, Гудящая Бездна находится к югу от лагерей стаи Древолапов.",
    [4136] = "Принесите голову Риббли Юке Крутипроб в Пылающие степи.",
    [4182] = "Убейте 15 детенышей черного дракона, 10 черных драконидов, 4 черных драконид и 1 черного дракона. По выполнении задания вернитесь к Хелендису Речному Мысу.",
    [4183] = "Отправьтесь в Приозерье и доставьте письмо Хелендиса Речного Мыса мировому судье Соломону.",
    [4184] = "Передайте обращение Соломона верховному лорду Болвару Фордрагону.$B$BБолвар Фордрагон пребывает в Крепости Штормграда.",
    [4185] = "Поговорите с Верховным лордом Болваром Фордрагоном после беседы с леди Катраной Престор.",
    [4186] = "Отнесите указ Болвара мировому судье Соломону в Приозерье.",
    [4201] = "Принесите 4 листа крови Грома, 10 огромных серебряных слитков и наполненный сосуд Нагмары госпоже Нагмаре в Глубины Черной горы.",
    [4223] = "Поговорите с маршалом Максвеллом в Пылающих степях.",
    [4224] = "Поговорите с Джоном-Оборванцем и узнайте о судьбе маршала Виндзора. По выполнении задания вернитесь к маршалу Максвеллу.$B$BКажется, маршал Максвелл говорил, что Джона следует искать в пещере на севере.",
    [4241] = "Отправляйтесь на Черную гору на северо-западе и войдите в ее глубины. Узнайте, что сталось с маршалом Виндзором.$B$BКажется, Джон-Оборванец говорил о том, что Виндзора утащили в темницу.",
    [4242] = "Сообщите маршалу Максвеллу плохие новости.",
    [4263] = "Отыщите и уничтожьте лорда Опалителя в глубинах Черной горы!",
    [4264] = "Не исключено, что ваша находка заинтересует маршала Виндзора. Может быть, все не так плохо, и надежда еще жива.",
    [4265] = "Освободите Раскала из улья Цуккаш.$B$BВернитесь к Гинро Пылающему Очагу в Крепости Оперенной Луны и сообщите ему, что Раскал жив и здоров.",
    [4266] = "Поговорите с Шандрисой Оперенной Луной в Крепости Оперенной Луны.",
    [4267] = "Отнесите донесение Раскала Грацине Силе Духа в Дарнассе.",
    [4281] = "Отнесите недоставленную посылку Хранителю дорог Фалфиндеру в Таланаар.",
    [4282] = "Верните маршалу Виндзору утерянную информацию.$B$BМаршал уверен, что информацией завладели повелитель големов Аргелмах и генерал Кузня Гнева.",
    [4286] = "Отправьтесь в глубины Черной горы и принесите 20 поясных сумок дворфов Черного Железа. По выполнении задания вернуться к Орелиусу. Предположительно поясные сумки можно отобрать у дворфов Черного Железа в глубинах Черной горы.",
    [4322] = "Помогите маршалу Виндзору забрать вещи и освободить его друзей, после чего вернитесь к маршалу Максвеллу и получите дальнейшие инструкции.",
    [4324] = "Переговорите с Юкой Крутипроб в Пылающих степях.",
    [4341] = "Пойдите в Глубины Черной горы и найдите Карана Могучего Молота.$B$BКороль упомянул, что Каран сидит там в плену – может, стоит поискать темницу.",
    [4342] = "Выслушайте рассказ Карана Могучего Молота.",
    [4361] = "Вернитесь в Стальгорн и сообщите нехорошие новости королю Магни Бронзобороду.",
    [4362] = "Вернитесь в Глубины Черной горы и освободите принцессу Мойру Бронзобород от злобного императора Даграна Тауриссана.",
    [4363] = "Вернитесь в Стальгорн и переговорите с королем Магни Бронзобородом.",
    [4487] = "Поговорите в Кабестане со Страхадом Фарсаном.",
    [4488] = "Поговорите в Кабестане со Страхадом Фарсаном.",
    [4489] = "Поговорите в Кабестане со Страхадом Фарсаном.",
    [4490] = "Поговорите в Кабестане со Страхадом Фарсаном, чтобы получить способность призывать коня Скверны.",
    [4701] = "Отправьтесь на пик Черной горы и уничтожьте источник опасности. Хелендис кричит вам вслед одно имя: Халикон. Именно его упоминали орки в связи с воргами.",
    [4724] = "Убейте Халикон, праматерь стаи воргов Кровавого Топора.",
    [4729] = "Отправьтесь на пик Черной горы и отыщите там щенков воргов легиона Кровавого Топора. Посадите маленьких тварей в клетку и отнесите Киблеру.",
    [4734] = "Испытайте прототип яйцехладоскопа на одном из яиц в Гнездовье.",
    [4735] = "Принесите 8 драконьих яиц и устройство-коллекционер Тинки Кипеллер в Пламенеющий Стяг в Пылающих степях.",
    [4742] = "Найдите самоцвет Тлеющего Терновника, самоцвет Черной Вершины и самоцвет Кровавого Топора. Верните их Ваелану вместе с простой печатью Вознесения.$B$BКамни могут быть у трех генералов: у воеводы Вуна из клана Тлеющего Терновника, у вождя Омокка из клана Черной Вершины и у повелителя Змейталака из клана Кровавого Топора.",
    [4743] = "Идите в Драконьи топи в Пылевых топях. Найдите Огнебора и бейте его, не жалея, чтобы сломить его волю.$B$BКак только воля великого зверя ослабнет, надо немедленно положить перед ним заготовку печати Вознесения и воспользоваться сферой Энергии дракона, чтобы подчинить себе его разум и направить его пламя на заготовку.",
    [4764] = "Принесите пряжку Роковой оснастки Майре Светлое Крыло в Пылающие степи.",
    [4765] = "Отнесите ящик Риджвелла Ремингтону Риджвеллу в Штормград.",
    [4766] = "Поговорите с Майрой в Пылающих степях.",
    [4768] = "Принесите табличку Темного Камня тенемагу Вивиан Лаграв в Каргат.",
    [4769] = "Переговорите с темным магом Вивианой Лягроб.",
    [4771] = "Отнесите \"Рассветный гамбит\" в Демонстрационную комнату в Некроситете. Уничтожьте Вектуса и возвращайтесь к Бетине Биггльцинк.",
    [4787] = "Принесите древнее яйцо Йе'кинье в Танарис.",
    [4788] = "Принесите пятую и шестую таблички Мошару геологу Железному Башмаку в Танарисе.",
    [4862] = "Отправьтесь на пик Черной горы и принесите Киблеру 15 яиц скального паука.$B$BСудя по всему, яйца надо искать недалеко от пауков.",
    [4866] = "Найдите в самом сердце пика Черной горы мать Дымную Паутину. Сражайтесь с ней, пока она не введет вам свой яд. Скорее всего ее также придется убить. Когда яд будет в вас, вернитесь к Джону-Оборванцу, чтобы он смог добыть яд.",
    [4867] = "Прочитайте записку Вароша. Принесите Варошу его амулет.",
    [4903] = "Убейте вождя Омокка, воеводу Вуна и повелителя Змейталака. Найденные при них важные бумаги Черной горы доставьте полководцу Клинозубу в Каргат.",
    [4907] = "Поговорите с Тинки Кипеллер.",
    [4921] = "Отыщите жену Манкрика и возвращайтесь к нему в Перекресток.",
    [4941] = "Поговорите с Эйтриггом в Оргриммаре. После этого обратитесь к вождю Траллу.$B$BВ последний раз Эйтригг был в в зале приемов Тралла.",
    [4974] = "Пойдите в Пик Черной горы и убейте вождя Ренда Чернорука. Принесите его голову в Оргриммар.",
    [4981] = "Отправьтесь к пику Черной горы и выясните, что сталось с Блестяшкой.",
    [4982] = "Найдите вещи Блестяшки и верните их владелице. Блестяшка сказала, что она спрятала свое оборудование где-то на нижнем ярусе подземелья.",
    [4983] = "Передайте донесение Блестяшки гроссмейстеру Лекслорту в Каргат.",
    [5001] = "Найдите вещи Блестяшки и верните их владелице. Удачи!",
    [5002] = "Передайте маршалу Максвеллу информацию Блестяшки.",
    [5047] = "Переговорите с Малифоем Черномолотом в Круговзоре.",
    [5061] = "Вернитесь в Дарнасс и покажите Матренгилу Медвежьей Лапе свою подвеску Морского Льва.",
    [5065] = "Принесите третью и четвертую таблички Мошару геологу Железному Башмаку в Танарис.",
    [5081] = "Отправляйтесь на пик Черной горы и устраните воеводу Вуна, вождя Омокка и повелителя Змейталака. По выполнении задания вернитесь к маршалу Максвеллу.",
    [5089] = "Отнесите приказ генерала Драккисата маршалу Максвеллу в Пылающие степи.",
    [5096] = "Отправляйтесь в лагерь Алого ордена между полем Джанис и Слезами Далсона и уничтожьте командный шатер.$B$BРазместите в лагере знамя Плети и возвращайтесь к верховному палачу Деррингтону в Бастион, в Западные Чумные земли.",
    [5097] = "Отметьте все башни Андорала при помощи сигнального факела; задействовать факел следует, находясь в дверном проеме каждой из башен.$B$BОтметив все четыре башни, следует вернуть сигнальный факел командиру Ашламу Отважному Кулаку в лагерь Промозглого Ветра в Западных Чумных землях.",
    [5098] = "Отметьте все башни Андорала при помощи сигнального факела; задействовать факел следует, находясь в дверном проеме каждой из башен.$B$BОтметив все четыре башни, следует вернуть сигнальный факел командиру Ашламу Смелонраву в лагерь Холодного Ветра в Западных Чумных землях.",
    [5102] = "Отправьтесь на пик Черной горы и устраните генерала Драккисата. По выполнении задания вернитесь к маршалу Максвеллу.",
    [5122] = "Укрывшись в этой часовне, я могу противостоять порче, заполняющей мое существо. Но если я покину эти стены, я немедленно превращусь в нежить. Я знаю, что есть на свете медальон, именуемый медальоном веры, который может дать мне силу противостоять порче.$B$BПрошу тебя, Димиллион, принеси мне медальон. Его охраняет безумный фанатик Малор Ревностный, один из Алых. Ты найдешь его в недрах бастиона Алого ордена в западной части Стратхольма.",
    [5125] = "Я умираю, Арраон… но душа моя обрела спасение. Я так многим обязан тебе... Прошу, прими это... И продолжай биться за правое дело, храбрый |3-6(Друид)!",
    [5127] = "Отправляйтесь на пик Черной горы и найдите Горалука Треснувшую Наковальню. Убейте его, а потом воткните в труп окровавленную пику. Таким образом пика вытянет его душу и окрасится ей.$B$BКроме того, вам нужно найти заготовку рунической кирасы.$B$BОтнесите пику и кирасу Лораксу в Зимних Ключах.",
    [5142] = "Найдите Памелу Редпат.",
    [5149] = "Найдите куклу Памелы.",
    [5152] = "Поговорите с Марлен в южной части руин Андорала.",
    [5153] = "Принесите Хроми обручальное кольцо Джозефа.",
    [5154] = "Принесите Анналы Дарроушира Хроми в Андорал.",
    [5160] = "Дойдите до Зимних Ключей и найдите Халех. Отдайте ей пластину чешуи Ауби.",
    [5163] = "Возьмите механического йети Уми и напугайте им ее друзей:$B$BЛегакки в Круговзоре (Зимние Ключи)$Bполивалку в Прибамбасске (Танарис)$BКвикксиля в Укрытии Маршалла (Кратер Ун'Горо)$B$BКогда проделаете все это, принесите механического йети обратно Уми.",
    [5168] = "Принесите книгу Дейвила и щит Крассена Карлину Редпату.",
    [5181] = "Принести череп Хоргуса и сломанный меч Мардука Карлину Редпату в Часовню Последней Надежды.",
    [5206] = "Принесите 5 резонирующих черепов и загадочный кристалл Карлину Редпату в Восточные Чумные земли.",
    [5210] = "Отнесите дополненные Анналы Дарроушира Карлину Редпату в Восточные Чумные земли.",
    [5211] = "Освободите 15 духов Дарроушира и возвращайтесь к Карлину Редпату.",
    [5212] = "Принесите 20 препаратов чумной плоти из Стратхольма Бетине Биггльцинк. Предположительно, любая тварь из Стратхольма сойдет за препарат.",
    [5213] = "Отправляйтесь в Стратхольм и исследуйте зиккураты. Доставьте сведения о Плети Бетине Биггльцинк.",
    [5214] = "Найдите табачную лавку Эзры Гримма в Стратхольме, отыщите в ней коробку отличного табака Эзры Гримма и принесите ее Дымку ЛаРу.",
    [5241] = "Найдите Карлина Редпата.",
    [5243] = "Отправляйтесь на север, в Стратхольм. Обыщите брошенные ящики с припасами и соберите 5 мер святой воды Стратхольма. Возвращайтесь к Леониду Бартоломею Чтимому, как только воды будет достаточно.",
    [5251] = "Отправляйтесь в Стратхольм и отыщите архивариуса Галфорда из Алого ордена. Убейте его и сожгите архив Алых.",
    [5262] = "Отнесите голову Бальназара герцогу Николасу Зверенхоффу в Восточные Чумные земли.",
    [5263] = "Отправляйтесь в Стратхольм и убейте барона Ривендера. Принесите его голову герцогу Николасу Зверенхоффу.",
    [5282] = "Стреляйте в призраков и неупокоенных на улицах Стратхольма из излучателя Эгана. Когда душа вырвется из призрачной оболочки, выстрелите в нее еще раз, и она обретет свободу.$B$BОсвободите 15 неупокоенных душ и возвращайтесь к Эгану.",
    [5341] = "Отправляйтесь в Некроситет и добудьте сокровище семьи Баровых. Оно состоит из четырех документов: на Каэр Дарроу, на Брилл, на Мельницу Таррен и на Южнобережье. После выполнения задания вернитесь к Алексию Барову.",
    [5342] = "Отправляйтесь в Лагерь Промозглого Ветра – на земли Альянса – и убейте Велдона Барова. Отнесите его голову Алексию Барову.$B$BСоблюдайте осторожность – скорее всего, Велдона охраняет мразь Альянса.",
    [5343] = "Отправляйтесь в Некроситет и добудьте сокровище семьи Баровых. Оно состоит из четырех документов: на Каэр Дарроу, на Брилл, на Мельницу Таррен и на Южнобережье. После выполнения задания вернитесь к Велдону Барову.",
    [5344] = "Отправляйтесь в Бастион – на земли Орды – и убейте Алексия Барова. Отнесите его голову Велдону Барову.$B$BСоблюдайте осторожность – скорее всего, Алексия охраняет ордынская мразь.",
    [5382] = "Найдите в Некроситете доктора Теолена Крастинова. Убейте его, затем сожгите останки Евы и Люсьена Саркофф. Выполнив задание, возвращайтесь к Еве Саркофф.",
    [5383] = "Отнесите мешок ужасов Еве Саркофф в Каэр Дарроу.",
    [5384] = "Вернитесь в Некроситет с кровью невинных. Найдите балкон и вылейте кровь в жаровню. На зов явится Киртонос.$B$BСражайтесь как герой, не сдавайтесь! Уничтожьте Киртоноса и возвращайтесь к Еве Саркофф.",
    [5461] = "Отправляйтесь в высокогорья Арати, в руины Стромгарда. Поищите в Стромгарде книгу Воспоминаний. Если удастся ее отыскать, отнесите ее мировому судье Мардуку.",
    [5462] = "Отправляйтесь в часовню Светлых надежд в Восточных Чумных землях и найдите Леонида Бартоломея Чтимого. Покажите ему книгу Воспоминаний и расскажите обо всем, о чем удалось узнать.",
    [5463] = "Отправляйтесь в Стратхольм и отыщите Дар Менетила. Положите книгу Воспоминаний на оскверненную землю.",
    [5464] = "Отнесите Книгу Души Леониду Бартоломею в Восточные Чумные земли.",
    [5465] = "Возвращайтесь к мировому судье Мардуку в Каэр Дарроу. Покажите ему Книгу Души.",
    [5466] = "Отыщите в Некроситете Раса Снегошепота. Найдя его, воспользуйтесь Книгой Души против его посмертного облика. Если удастся превратить Раса в смертного, убейте его и заберите человеческую голову Раса Снегошепота. Отнесите голову мировому судье Мардуку.",
    [5514] = "Отнесите Кринкелю Сталлинну из Прибамбасска прочные фрагменты скелета и 15 золотых монет.",
    [5515] = "Найдите в Некроситете Джандис Баров и уничтожьте ее. Заберите мешок ужасов Крастинова. Отнесите мешок Еве Саркофф.",
    [5518] = "Принесите 4 рулона рунной ткани, 8 кусков прочной кожи, 2 мотка рунной нити и огрскую дубильную кислоту Уззлу Наперстяку. Он прикован в секторе клана Гордок в Забытом Городе.",
    [5525] = "Эта вещь называется \"ключ от оков Гордока\" – по крайней мере, так называют его эти \"остроумцы\". Думаю, такой ключ может быть у любого из огров, но у кого именно – сказать не возьмусь. Есть вероятность, что такие ключи имеются у стражников…$B$BНо о чем я говорю? Он у вас есть, да? Он при вас?!",
    [5528] = "Ну, ты теперь у нас большая шишка, так попробуй задаром моего лучшего пойла! Оно и сил добавляет, и голову кружит! Пей, пей, начальник – попробуй, сам увидишь!",
    [5529] = "Убейте 20 зачумленных детенышей дракона, затем возвращайтесь к Бетине Биггльцинк в Часовню Последней Надежды.",
    [5531] = "Принесите охлажденные яйца Бетине Биггльцинк.",
    [5533] = "Поговорите с алхимиком Арбингтоном с вершины Холодной Скалы, что в Западных Чумных землях.",
    [5537] = "Принесите 15 фрагментов скелетов алхимику Арбингтону в Берег Промозглого Ветра в Западных Чумных землях.",
    [5538] = "Отнесите Кринкелю Сталлинну из Прибамбасска прочные фрагменты скелета и 15 золотых монет.",
    [5582] = "Отнесите здоровую чешую дракона Бетине Биггльцинк в Часовню Последней Надежды в Восточные Чумные земли.",
    [5601] = "Найдите Памелу Редпат в Дарроушире.",
    [5721] = "Положите сверток с реликвиями на городскую площадь Дарроушира.$B$BПредотвратите смерть Дейвила Яркосвета от рук Хоргуса.$B$BНе допустите смерти капитана Редпата до появления Редпата Оскверненного.$B$BУбейте Редпата Оскверненного.$B$BПоговорите с духом Джозефа Редпата, когда он вновь появится на городской площади, затем отправляйтесь к Памеле и поговорите с ней.",
    [5742] = "Выслушайте Тириона Фордринга.",
    [5762] = "Отнесите ящик Крейвела Хемингу Эрнестуэю в Тернистую долину.",
    [5763] = "Отнесите рог кодо, принадлежащий Руну, Хемингу Эрнестуэю в Тернистую долину.",
    [5781] = "Отправляйтесь в Крипту – в самой южной части Восточных Чумных земель – и добудьте молот Таэлана. Отнесите его Тириону Фордрингу.",
    [5801] = "Отнесите форму для отливки отмычек и 2 ториевых слитка на вершину Вулкана Огненного Венца в Кратере Ун'Горо. Окуните форму для отливки отмычки в озеро лавы. Получится недоделанная отмычка.$B$BОтнесите недоделанную отмычку алхимику Арбингтону на Берег Промозглого Ветра в Западные Чумные земли.",
    [5802] = "Отнесите форму для отливки отмычек и 2 ториевых слитка на вершину Вулкана Огненного Венца в Кратере Ун'Горо. Окуните форму для отливки отмычки в озеро лавы. Получится недоделанная отмычка.$B$BОтнесите недоделанную отмычку аптекарю Дитерсу в Бастион, что в Западных Чумных землях.",
    [5803] = "Убейте Аража Призывателя отнесите его скарабея алхимику Арбингтону на Берег Промозглого Ветра, что в Западных Чумных землях.",
    [5804] = "Убейте Аража Призывателя и отнесите его скарабея аптекарю Дитерсу в Бастион, что в Западных Чумных землях.",
    [5845] = "Отправляйтесь в Северный дол, что в северо-восточной части Восточных Чумных земель и найдите там символ утраченной чести. После этого вернитесь к Тириону Фордрингу.",
    [5846] = "Отправляйтесь на остров Каэр Дарроу в центральной части Чумных земель и поищите там картину.",
    [5848] = "Отправляйтесь в Статхольм в северную часть Чумных земель. Найдите в Бастионе Алого ордена картину \"Символ семейной любви\", спрятанную за другой, изображающей две луны нашего мира.$B$BОтнесите картину Тириону Фордрингу.",
    [5861] = "Отправляйтесь к гробнице Утера, которая находится в южных Чумных землях. Покажите Миранде Колдунье подарок Тириона.",
    [5862] = "Поговорите с Мирандой, пусть она наложит на вас Алую иллюзию. Отправляйтесь в Дольный Очаг, покуда она действует, и отнесите подарок Тириона верховному лорду Телану Фордрингу.$B$BДольный Очаг на севере, а Таэлан должен быть внутри Крепости Марденхольд.",
    [5921] = "При помощи заклинания \"Телепортация: Лунная поляна\" перенеситесь в Лунную поляну. По прибытии поговорите с Дендритом Блеском Звезд в селении Ночная Гавань.",
    [5922] = "При помощи заклинания \"Телепортация: Лунная поляна\" перенеситесь в Лунную поляну. По прибытии поговорите с Дендритом Блеском Звезд в селении Ночная Гавань.",
    [5923] = "Поговорите с Матренгилом Медвежьей Лапой в анклаве Кенария в Дарнассе.",
    [5924] = "Поговорите с Матренгилом Медвежьей Лапой в анклаве Кенария в Дарнассе.",
    [5925] = "Поговорите с Матренгилом Медвежьей Лапой в анклаве Кенария в Дарнассе.",
    [5926] = "Поговорите с Тюраком Руническим Тотемом на Вершине Старейшин Громового Утеса.",
    [5927] = "Поговорите с Тюраком Руническим Тотемом на Вершине Старейшин в Громовом Утесе.",
    [5928] = "Поговорите с Тюраком Руническим Тотемом на Вершине Старейшин в Громовом Утесе.",
    [5929] = "Найдите духа Великого Медведя на северо-западе Лунной поляны и усвойте все, что он расскажет вам о природе медведя. Когда уроки будут закончены, вернитесь к Дендриту Блеску Звезд в Ночную Гавань в Лунной поляне.",
    [5930] = "Найдите духа Великого Медведя на северо-западе Лунной поляны и усвойте все, что он расскажет вам о природе медведя. Когда уроки будут закончены, вернитесь к Дендриту Блеску Звезд в Ночную Гавань в Лунной поляне.",
    [5931] = "Вернитесь в Дарнасс и поговорите с Матренгилом Медвежьей Лапой в анклаве Кенария.",
    [5932] = "Вернитесь в Громовой Утес и поговорите с Тюраком Руническим Тотемом на Вершине Старейшин.",
    [5941] = "Отнесите сумку с реликвиями Хроми в Андорал.",
    [5942] = "Откройте сундук Джозефа ключом Джозефа.",
    [5944] = "Вывести Таэлана Фордринга из Дольного Очага.",
    [6001] = "Посыпьте лунной пылью Кенария камень лунного совуха в Аубердине, чтобы вызвать Лунокогтя. Победите Лунокогтя, чтобы получить силу его тела и духа.$B$BЗатем поговорите с Матренгилом Медвежьей Лапой в Дарнассе.",
    [6002] = "Посыпьте лунной пылью Кенария Камень Лунного совуха, что между Мулгором и Степями, чтобы вызвать Лунокогтя. Теперь вам надо побороть Лунокогтя, чтобы заслужить его силу духа и тела.$B$BКогда выполните это, поговорите с Тюраком Руническим Тотемом в Громовом Утесе.",
    [6004] = "Убейте 2 медиков, 2 охотников, 2 волхвов и 2 рыцарей Алого ордена и вернитесь к Кристе Чернотени в Западных Чумных землях.",
    [6023] = "Убейте охотника Радли и кавалериста Даргена и вернитесь к Кристе Чернотени в Западные Чумные земли.",
    [6025] = "Проберитесь в Дольный Очаг и найдите возвышенность, с которой открывается вид на весь город. Оцените силы Алого ордена и вернитесь к Кристе Чернотени в Западных Чумных землях.",
    [6061] = "Приручите взрослого равнинного долгонога при помощи хлыста приручения. Потренируйтесь и верните хлыст Йо Колкой Гриве в Деревне Кровавого Копыта.",
    [6062] = "Приручите лютого пятнистого вепря с помощью хлыста приручения. Потренируйтесь, потом верните хлыст приручения Тотару в Колючем Холме.",
    [6063] = "С помощью хлыста приручения приручите чащобного тенетника. Поупражняйтесь, затем верните хлыст приручения Дазалару в Доланаар.",
    [6064] = "Приручите большого скального вепря с помощью хлыста приручения. Потренируйтесь со своим новым питомцем, а затем верните хлыст приручения Грифу Дикому Сердцу в Каранос.",
    [6065] = "Поговорите с Йо Колкой Гривой в Деревне Кровавого Копыта.",
    [6066] = "Поговорите с Йо Колкой Гривой в Деревне Кровавого Копыта.",
    [6067] = "Поговорите с Йо Колкой Гривой в Деревне Кровавого Копыта.",
    [6068] = "Поговорите с Тотаром в Колючем Холме.",
    [6069] = "Поговорите с Тотаром в Колючем Холме.",
    [6070] = "Поговорите с Тотаром в Колючем Холме.",
    [6071] = "Поговорите в Доланааре с Дазаларом.",
    [6072] = "Поговорите в Доланааре с Дазаларом.",
    [6073] = "Поговорите в Доланааре с Дазаларом.",
    [6074] = "Поговорите с Грифом Диким Сердцем в Караносе.",
    [6075] = "Поговорите с Грифом Диким Сердцем в Караносе.",
    [6076] = "Поговорите с Грифом Диким Сердцем в Караносе.",
    [6081] = "Поговорите с Ормаком Лютострелом в Оргриммаре.",
    [6082] = "Приручите бронескорпа с помощью хлыста приручения. Потренируйтесь, потом вернитесь к Тотару в Колючем Холме.",
    [6083] = "Приручите приливного краба с помощью хлыста приручения. Потренируйтесь, потом верните хлыст приручения Тотару в Колючем Холме.",
    [6084] = "Приручите снежного леопарда с помощью хлыста приручения. Потренируйтесь со своим новым питомцем, а затем верните хлыст приручения Грифу Дикому Сердцу в Каранос.",
    [6085] = "Приручите медведя-ледолапа с помощью хлыста приручения. Потренируйтесь со своим новым питомцем, а затем верните хлыст приручения Грифу Дикому Сердцу в Каранос.",
    [6086] = "Поговорите в с Белией Громовым Гранитом в Стальгорне.",
    [6087] = "Приручите охотника прерий при помощи хлыста приручения. Потренируйтесь и верните хлыст Йо Колкой Гриве в Деревне Кровавого Копыта.",
    [6088] = "Приручите перепелятника при помощи хлыста приручения. Потренируйтесь и верните хлыст Йо Колкой Гриве в Деревне Кровавого Копыта.",
    [6089] = "Поговорите с Хольтом Громовым Рогом в Громовом Утесе.",
    [6101] = "С помощью хлыста приручения приручите ночного саблезуба-охотника. Поупражняйтесь, затем верните хлыст приручения Дазалару в Доланаар.",
    [6102] = "С помощью хлыста приручите совиного крикуна. Поупражняйтесь, затем верните хлыст приручения Дазалару в Доланаар.",
    [6103] = "Поговорите с Иокастой в анклаве Кенария в Дарнассе.",
    [6121] = "Отправляйтесь в Лунную поляну и поговорите с Дендритом Блеском Звезд в селении Ночная Гавань.",
    [6122] = "Используйте пустую колбу для взятия пробы воды из устья пещеры у водопада Скалистый.$B$BДоставьте наполненную колбу Аландариан Песне Ночи в Аубердин, на Темный Берег.",
    [6123] = "Принесите 5 корешков землекорня и 12 лунных грибов Аландариан Песне Ночи в Аубердине, чтобы она могла сделать целительную мазь.",
    [6124] = "Нанесите мазь исцеления животных на 10 больных оленей, обитающих на Темном Берегу, – это должно их исцелить. По слухам, ареал обитания больных оленей – южнее реки Скалистой и севернее Аубердина, а далее – по всей области, вплоть до южных границ Темного Берега, где начинается Ясеневый лес.",
    [6125] = "Вернитесь к Матренгилу Медвежьей Лапе в анклав Кенария в Дарнассе.",
    [6126] = "Отправляйтесь в Лунную поляну и поговорите с Дендритом Блеском Звезд в селении Ночная Гавань.",
    [6127] = "Используйте пустой пробоотборник Вершины Багрового Тумана для отбора воды из озера на вершине.$B$BДоставьте наполненный пробоотборник Вершины Багрового Тумана Тонге Руническому Тотему в Перекресток, что в Степях.",
    [6128] = "Принесите 5 корешков землекорня и 5 рогов кодо Тонге Руническому Тотему в Перекресток, и он сделает целебную мазь.",
    [6129] = "Нанесите мазь исцеления животных на 10 больных газелей, обитающих в северной части Степей, – это должно их вылечить. По слухам, больные газели живут севернее дороги, проходящей через Перекресток с востока на запад.",
    [6130] = "Вернитесь к Тюраку Руническому Тотему на Вершину Старейшин в Громовой Утес.",
    [6141] = "Найдите в Пустошах брата Антона и поговорите с ним.",
    [6144] = "Отправляйтесь в Подгород и предстаньте перед Вериматасом.",
    [6145] = "Возвращайтесь в Восточные Чумные земли и выследите курьера из Багрового Легиона. Убейте его и заберите приказ верховного рыцаря.$B$BЗа дальнейшими указаниями обращайтесь к Натаносу Гнилостеню.",
    [6146] = "Отправляйтесь в Длань Тира к юго-востоку от Поместья Маррисов. Прибыв в город, откусите от гнилого яблока. Под личиной рыцаря Алого ордена доставьте приказ верховного рыцаря лорду-рыцарю Вальдермару.",
    [6147] = "Возвращайтесь к Натаносу и отчитайтесь о выполнении задания.",
    [6148] = "Алый орден сейчас в пути. Найдите Оракула Деметрию и ее свиту на дороге от Длани Тира в Стратхольм. Убейте Оракула и возвращайтесь к Натаносу Гнилостеню.",
    [6163] = "Отправляйтесь в Стратхольм и убейте Рамштайна Ненасытного. Принесите его голову Натаносу в качестве сувенира.",
    [6402] = "Отправьтесь в Штормград и подойдите к городским воротам. Поговорите с оруженосцем Роу, чтобы он сообщил маршалу Виндзору о вашем прибытии.",
    [6403] = "Сопроводите Реджинальда Виндзора через весь Штормград. Защитите его!",
    [6501] = "Найдите существа, способные вернуть силу фрагменту амулета Ока дракона. Все, что об этих существах известно – это то, что они есть.",
    [6502] = "Добудьте кровь могучего черного дракона генерала Драккисата, которого можно найти сидящим на троне в залах Вознесения в Пике Черной горы.",
    [6566] = "Выслушайте Тралла.",
    [6567] = "Найдите Рексара. Вождь сказал, что он бродит в Пустошах, по дороге, что ведет из Когтичтых гор в Фералас.",
    [6568] = "Доставьте письмо Рексара Миранде Колдунье в Западные Чумные земли.",
    [6569] = "Отправляйтесь на пик Черной горы и добудьте 20 глаз черных драконидов. По выполнении задания вернитесь к Миранде Колдунье.",
    [6570] = "Отправляйтесь в Драконьи топи в Пылевых топях и найдите Логово Огнебора. Оказавшись внутри, наденьте амулет Обмана драконов и поговорите с Огнебором.",
    [6582] = "Найдите в Зимних Ключах избранного бойца синих дракона по имени Провидец и убейте его. С его черепом вернитесь к Огнебору.",
    [6583] = "Убейте вожака зеленых драконов Сомнуса и вернитесь с его черепом к Огнебору.",
    [6584] = "Убейте Хроналиса, охраняющего Пещеры Времени в Пустыне Танарис и вернитесь с его черепом к Огнебору.",
    [6585] = "Отправьтесь в Грим Батол и убейте Акстроза, избранного бойца красных драконов. Принесите его череп Огнебору.",
    [6601] = "Казалось бы, загадка разгадана. Вы знаете, что амулет Обмана Драконов, который сделала для вас Миранда Колдунья, не будет работать на пике Черной горы. Найдите Рокаро и расскажите о ваших затруднениях. Покажите ему амулет Угасающего Пламени Дракона. Будем надеяться, он знает что делать.",
    [6602] = "Отправляйтесь к пику Черной горы и убейте генерала Драккисата. Соберите его кровь и вернитесь к Рокаро.",
    [6681] = "Отнесите печать Черного Ворона Фахраду в поместье Черный Ворон, сокрытое среди холмов Хилсбрада.$B$BНе теряйте бдительности. Поиски поместья – проверка на ловкость.",
    [6721] = "Поговорите в Доланааре с Дазаларом.",
    [6722] = "Поговорите в Доланааре с Дазаларом.",
    [6981] = "Отправляйтесь в Кабестан и найдите там кого-нибудь, кто сможет вам рассказать об этом светящемся осколке.$B$BЗатем отнесите осколок туда, куда вас направят.",
    [7028] = "Соберите 25 терадрических хрустальных орнаментов для Ивы из Пустошей.",
    [7029] = "Наполните церуленовый фиал с покрытием в оранжевом пруду Мародона.$B$BПолейте гнусь-лозу из полного церуленового фиала, выгнав ядовитую лозу.$B$BИсцелите 8 растений, убивая ядовитые лозы, и вернитесь к Варку Боевому Шраму в Деревню Ночных Охотников.",
    [7041] = "Наполните церуленовый фиал с покрытием в оранжевом пруду Мародона.$B$BПолейте гнусь-лозу из полного церуленового фиала, выгнав ядовитую лозу.$B$BИсцелите 8 растений, убивая ядовитые лозы, и вернитесь к Талендрии из Высоты Найджела.",
    [7044] = "Добудьте две части скипетра Келебраса – жезл Келебраса и бриллиант Келебраса.$B$BНайдите способ поговорить с Келебрасом.",
    [7046] = "Помогите Селебрасу Искупленному воссоздать скипетр Селебраса.$B$BПо завершении ритуала снова обратитесь к нему.",
    [7064] = "Убейте принцессу Терадрас и вернитесь к Селендре неподалеку от Деревни Ночных Охотников в Пустошах.",
    [7065] = "Убейте принцессу Терадрас и вернитесь к хранителю Марандису на Высоту Найджела в Пустоши.",
    [7066] = "Найдите в Лунной поляне Ремулоса и отдайте ему Семя Жизни.",
    [7067] = "Прочтите инструкции кентавра-парии, добудьте из Мародона амулет Соединения и верните его кентавру-парии из южной части Пустошей.",
    [7068] = "Соберите в Мародоне 10 фрагментов осколков сумрака и отнесите их Утель'наю в Оргриммар.",
    [7070] = "Соберите в Мародоне 10 фрагментов осколков сумрака и отнесите их верховному магу Тервошу в Терамор на побережье Пылевых топей.",
    [7201] = "Отправляйтесь в Глубины Черной горы и добудьте 10 мер сущности Стихий. Стоит начать поиски с големов и их создателей. Вивиан Лаграв также бормотала что-то про элементалей.",
    [7441] = "Отправляйтесь в Забытый Город и отыщите беса Пузиллина. Любыми доступными средствами убедите Пузиллина отдать вам книгу заклинаний Аж'Тордина.$B$BЕсли добудете книгу, вернитесь к Аж'Тордину в павильон Лорисс в Фераласе.",
    [7461] = "Перебейте стражей, которые охраняют 5 столпов, снабжающих энергией Тюрьму Бессмер'тера. После того как столпы угаснут, силовое поле, удерживающее Бессмер'тера, рассеется.$B$BВойдите в Тюрьму Бессмер'тера и уничтожьте злого демона, который находится внутри. И, наконец, сразитесь с принцем Тортелдрином в Читальне.$B$BЕсли задание будет выполнено успешно, вернитесь во двор, к прародительнице Шен'дралар.",
    [7462] = "Вернитесь в Читальню и найдите сокровище Шен'дралар. Получите свою награду!",
    [7463] = "Ступайте в Квартал Криводревов Забытого Города и убейте элементаля воды Гидротварь. Вернитесь в Читальню к сказителю Лидросу и принесите ему сущность Гидротвари.",
    [7481] = "Отыщите в Забытом Городе Тельмия Сновидца. Вернитесь в лагерь Мохаче к ведуну Королуску и сообщите ему все, что вам удалось узнать.",
    [7482] = "Отыщите в Забытом Городе Тельмия Сновидца. Вернитесь в крепость Оперенной Луны к исследовательнице Рунический Шип и сообщите ей все, что вам удалось узнать.",
    [7488] = "Принесите сеть Лефтендрис Латроникусу Лунному Копью в Крепость Оперенной Луны в Фераласе.",
    [7489] = "Принесите сеть Лефтендрис Тало Терновому Копыту в Лагере Мохаче в Фераласе.",
