    [7497] = "Драконоубийца и $Gопытный кожевник:опытная кожевница;? Ты не перестаешь изумлять меня, герой. Я сражен.$B$BПожалуйста, прими как дар то, чему я собираюсь тебя научить. Это знание окажется бесценным для тебя, если ты намерен уничтожить последних черных драконов.$B$BИзготовь плащ из чешуи драконьей царицы. Он будет защищать тебя и твоих союзников от опаляющего дыхания владыки Черной горы... Нефариана.",
    [7498] = "Верните книгу законным владельцам.",
