    [7505] = "Верните книгу законным владельцам.",
    [7506] = "Верните книгу законным владельцам.",
    [7507] = "Верните \"Справочник Ностро по убийству драконов\" в Читальню.",
    [7508] = "Отдайте тусклый и плоский эльфийский клинок сказителю Лидросу.",
    [7509] = "Заставьте Ониксию дохнуть своим огненным дыханием на потускневший древний клинок. После этого схватите раскаленный древний клинок. Имейте в виду, что раскаленным он останется ненадолго, так что медлить не следует!$B$BПоследнее, что нужно сделать – это убить драконицу и вонзить раскаленный древний клинок в ее труп.$B$BСделайте это – и Кель-Серрар навеки станет вашим!",
    [7562] = "Поговорите с Мор'зулом Кровопуском в Пылающих степях.",
    [7563] = "Принесите 30 бутылок крови яростных зверей Мор'зулу Кровопуску в Пылающие степи.",
    [7564] = "Принесите ларец Крови Горзиеки Дикоглазу в Пылающие степи.",
    [7604] = "Подпишите договор с представителем братства Тория Локтосом Недобрым Торговцем, если вам нужен чертеж сульфуронского молота.",
    [7623] = "Купите зелья Теней у Горзиеки в Пылающих степях.$B$BПриняв зелья, пройдите в Джеденар и поговорите с лордом Гиблопустом.",
    [7624] = "Сразитесь с Улатеком и принесите сердце предателя лорду Гиблопусту в Джеденар.",
    [7625] = "Купите зоротианскую звездную пыль у Ур'Дана. Отнесите ее Горзиеки Дикоглазу в Пылающие степи.",
    [7626] = "Отнесите 10 эликсиров Силы Теней Горзиеки Дикоглазу в Пылающие степи.",
    [7627] = "Отнесите 6 больших блестящих осколка и 25 кусков руды черного железа Дикоглазу в Пылающие степи.",
    [7628] = "Принесите 35 шкур черного дракона Горзиеки Дикоглазу в Пылающие степи.",
    [7629] = "Отнесите беса в бутылке в алхимическую лабораторию Некроситета. После создания пергамента верните бутылку Горзиеки Дикоглазу.",
    [7630] = "Принесите 3 арканитовых слитка Горзиеки в Пылающие степи.",
    [7631] = "Прочтите инструкции Мор'зула. Призовите ксоротианского коня погибели, одолейте его и подчините его дух.",
    [7632] = "Найдите хозяина древнего окаменелого древесного листа. Удачи, $N, мир велик.",
    [7634] = "Хастат Древний просит вас принести ему жилу взрослого синего дракона. По выполнении задания возвращайтесь к Хастату в Оскверненный лес.",
    [7635] = "Стома Древний просит вас принести ему жилу взрослого черного дракона. Добыв жилу, возвращайтесь к Стоме в Оскверненный лес.",
    [7636] = "Вы должны найти и уничтожить следующих четверых демонических разносчиков порчи :$B$BСимон Совратительницу.$B$BКлинфрана Безумного.$B$BСоленора Убийцу.$B$BАрториуса Судьбоносного.$B$BУничтожьте этих тварей и возвращайтесь к Вартусу Древнему в Оскверненный лес с их головами.$B$BВ поисках местонахождения этих демонов сверяйтесь с окаменевшей корой.$B$BВы ОБЯЗАНЫ выполнить это задание в одиночку.",
    [7637] = "Доберитесь до Стальгорна и получите курильницу экзорцизма у Верховного жреца Рохана. За курильницу нужно будет внести плату в размере 150 золотых монет.",
    [7638] = "Поговорите с лордом Грейсоном Тенеломом в Храмовом квартале Штормграда.",
    [7639] = "Принесите курильницу экзорцизма лорду Грейсону Тенелому в Храмовый квартал Штормграда.",
    [7640] = "Используйте курильницу экзорцизма для вызова из-под земли призраков, мучающих Долину Ужаса. Когда убьете 25 духов долины Ужаса, вернитесь к лорду Грейсону Тенелому в Храмовый квартал Штормграда.",
    [7641] = "Поговорите с Гримандом Элмором в Квартале Дворфов Штормграда.",
    [7642] = "Принесите Гриманду Элмору в Квартал Дворфов Штормграда 40 отрезов рунной ткани, 6 арканитовых слитков, 10 цветков слезы Артаса, 5 сосудов со святой водой Стратхольма и 150 золотых монет.",
    [7643] = "Купите лошадиный корм для Духа древнего коня у Меридет Карлсон в Южнобережье.$B$BУбейте Тендриса Криводрева в башне Забытого Города в Фераласе и освободите духа. Накормите духа кормом и получите благословление для арканитового чепрака.",
    [7644] = "Вернитесь вместе с благословенным арканитовым чепраком к лорду Грейсону Тенелому в Храмовый квартал Штормграда.",
    [7645] = "Принесите 20 витаминизированных печений из манны – ключевых составляющих обогащенного манной лошадиного корма – Меридет Карлсон в Южнобережье в предгорьях Хилсбрада. Продаются они только в Серебряном Рассвете.$B$BКроме того, понадобится дать ей 50 золотых, чтобы успокоить ее ущемленное самолюбие.",
    [7646] = "Принесите азеротский алмаз и безупречный черный алмаз лорду Грейсону Тенелому в Храмовый квартал Штормграда.",
    [7647] = "Используйте магический кристалл в центре подвала Главного склепа в Некроситете. Победите вызванных духов, а затем – рыцаря смерти Темного Терзателя, который появится после поражения духов.$B$BВерните падшему скакуну Темного Терзателя его спасенную душу и покройте его благословенным зачарованным чепраком.",
    [7648] = "Покажите арканитовый чепрак лорду Грейсону Тенелому в Храмовом квартале Штормграда.",
    [7703] = "Добудьте латную рукавицу мощи Гордока и вернитесь с ней к капитану Давигрому в Забытом Городе.$B$BПо словам Давигрома, в \"старых байках\" говорится, что Тортелдрин – \"страшный эльф\", называющий себя принцем, – похитил эту рукавицу у одного из королей клана Гордок.",
    [7761] = "Вот уж действительно идиот... Похоже, вам нужно найти это клеймо и выжечь на руке метку Драккисата, чтобы получить доступ к сфере Приказа.$B$BВ письме ясно сказано, что генерал Драккисат охраняет клеймо. Наверное, стоит проверить.",
    [7785] = "Изучите Сосуд Возрождения и вернитесь к верховному лорду Демитриану.",
    [7786] = "Чтобы освободить Громораана Ветроносца из тюрьмы, отнесите правый и левый наручник Ветроносца, 10 слитков элементия и сущность Повелителя огня верховному лорду Демитриану.",
    [7787] = "Отдайте Дремлющий клинок Игривого Ветра верховному лорду Демитриану.",
    [7877] = "Вернитесь в Читальню и найдите сокровище Шен'дралар. Получите свою награду!",
