    [8410] = "Соберите образцы воздуха, огня, земли и воды по поручению Бат'ры Ветростража.",
    [8412] = "Принесите части тотема Духа Бат'ре Ветростражу.",
    [8921] = "Принести Муксу Маноскребу из Прибамбасска 1 сверхточный арканитовый преобразователь, 4 великих вечных субстанции, 10 порций масла каменного угря, 25 горстей вулканического пепла и 40 золотых.",
    [8922] = "Отнесите запечатанный контейнер с кровью Муксу Маноскребу в Прибамбасск в Танарисе.",
    [8923] = "Отнесите запечатанный ларчик с ядом Муксу Маноскребу в Прибамбасск.",
    [8924] = "Воспользуйтесь эктоплазматическим дистиллятором рядом с бестелесной нежитью и соберите 12 образцов опаленной эктоплазмы в Силитусе, 12 образцов замороженной эктоплазмы в Зимних Ключах и 12 образцов стабильной эктоплазмы в Восточных Чумных землях. Принесите их вместе с эктоплазматическим дистиллятором Муксу Маноскребу в Прибамбасск.",
    [8925] = "Отыщите в Пылающих степях Повелителя магмы Бокка, добудьте его магмовое ядро и отнесите его Муксу Маноскребу в Прибамбасск.",
    [8928] = "Отыщите беса в пещере у входа в Теснину Зловещего Шепота в южной части Зимних Ключей, купите жезл Скверны Стихий и отнесите его Муксу Маноскребу в Прибамбасск.",
    [8929] = "Используйте спектральный сканер иных измерений на входе в Стратхольм и поговорите с духом Антиона Хармона.",
    [8930] = "Используйте спектральный сканер иных измерений на входе в Стратхольм и поговорите с духом Антиона Хармона.",
    [8945] = "Отправляйтесь в Стратхольм и спасите Исиду Хармон от Барона Ривендера.",
    [8946] = "Отнесите медальон Исиды Антиону Хармону в Восточные Чумные земли.",
    [8947] = "Принести три слитка черного железа, 20 кусков зачарованной кожи, 3 куска луноткани и 4 обработанные грубые шкуры Антиону Хармону в Восточные Чумные земли.",
    [8948] = "Отнесите незаконченное Знамя Вызова Фалрину Садовнику в библиотеку Забытого Города.",
    [8949] = "Соберите 25 боевых ожерелий огров с огров Забытого Города или пика Черной горы и вернитесь в Читальню Забытого Города к Фалрину Садовнику.",
    [8950] = "Принесите 1 сущность язвительного призрака, 4 черных руны и 8 больших сияющих осколков Фалрину Садовнику в Забытом Городе.",
    [8960] = "Отыщите Бодли у Пика Черной горы с помощью спектрального сканера иных измерений.",
    [8961] = "Добыть огневит Огнеуса, уголь Пиростража и пепел Герцога и принести их Бодли в Черную гору вместе с жаровней Благословения.",
    [8962] = "Найдите останки друидов и принести их Бодли в Черную гору.",
    [8963] = "Найдите реликвию Деревни Звездного Ветра и принести ее Бодли в Черную гору.",
    [8964] = "Добудьте бриллиантовый меч фанатизма и принесите его Бодли в Черную гору.",
    [8965] = "Добыть пепел душ Изгнанников и принести его Бодли в Черную гору.",
    [8966] = "Вызвать дух Мора Серого Копыта с помощью жаровни Призыва, прикончить его и забрать недостающую часть амулета Лорда Вальтхалака. Вернуться к Бодли в Черную гору, отдать ему левую часть амулета Вальтхалака и жаровню Призыва.",
    [8967] = "С помощью жаровни Призыва вызвать дух Изалиен и убить ее. Вернуться к Бодли в Черную гору, отдать ему левую часть амулета Лорда Вальтхалака и жаровню Призыва.",
    [8968] = "Вызвать духов Джариен и Сотоса с помощью жаровни Призыва и убить их обоих. Вернуться к Бодли в Черную гору, отдать ему левую часть амулета Лорда Вальтхалака и жаровню Призыва.",
    [8969] = "С помощью жаровни Призыва вызвать дух Кормока и убить его. Вернуться к Бодли в Черную гору, отдать ему левую часть амулета Лорда Вальтхалака и жаровню Призыва.",
    [8970] = "Собрать 20 порций кровавой ламинарии у наг из клана Страшаз и принести их Бодли в Черную гору.",
    [8977] = "Принесите спектральный сканер иных измерений Делиане в Стальгорн.",
    [8978] = "Принесите Моквару в Оргриммар спектральный сканер иных измерений.",
    [8985] = "Найдите реликвию Деревни Звездного Ветра и принести ее Бодли в Черную гору.",
    [8986] = "Найдите останки друидов и принести их Бодли в Черную гору.",
    [8987] = "Добудьте бриллиантовый меч фанатизма и принесите его Бодли в Черную гору.",
    [8988] = "Добыть пепел душ Изгнанников и принести его Бодли в Черную гору.",
    [8989] = "Вызвать дух Мора Серого Копыта с помощью жаровни Призыва, прикончить его и забрать недостающую часть амулета Лорда Вальтхалака. Вернуться к Бодли в Черную гору, отдать ему восстановленный амулет и жаровню Призыва.",
    [8990] = "С помощью жаровни Призыва вызвать дух Изалиен и убить ее. Вернуться к Бодли в Черную гору, отдать ему восстановленный амулет и жаровню Призыва.",
    [8991] = "Вызвать духов Джариен и Сотоса с помощью жаровни Призыва и убить их обоих. Вернуться к Бодли в Черную гору, отдать ему восстановленный амулет и жаровню Призыва.",
    [8992] = "С помощью жаровни Призыва вызвать дух Кормока и убить его. Вернуться к Бодли в Черную гору, отдать ему восстановленный амулет и жаровню Призыва.",
    [8994] = "Соберите 40 наручей Черной горы и разыщите склянку Великой силы. Отнесите все это Бодли в Черную Скалу.",
    [8995] = "Вызвать Лорда Вальтхалака с помощью жаровни Призыва. Убить его и использовать амулет. Потом вернуть амулет духу Вальтхалака.",
    [8996] = "Вернитесь к Бодли в Черную гору и отдайте ему жаровню Призыва.",
    [8997] = "Поговорите с Делианой в Высоком троне в Стальгорне.",
    [9015] = "Войдите в Зал Правосудия в Глубинах Черной горы, выслушайте приговор верховного судьи Мрачнокамня и вонзите знамя Вызова в центр круга. Убейте Телдрена и его гладиаторов, после чего вернитесь к Антиону Хармону в Восточные Чумные земли с первой частью амулета Лорда Вальтхалака.",
    [9362] = "Принесите радужную раковину верховному магу Ксилему в башню в утесах Азшары.",
    [9364] = "Наложите заклинание превращения на тварей Бича Злобы в Азшаре и убейте клонов, которые появятся несколько мгновений спустя. Убейте 50 клонов и возвращайтесь к верховному магу Ксилему в Азшару.",
    [78261] = "Найдите рог Кселтоса в крепости Темного Клыка и верните его в тайник С у деревни Погребальных Костров. Идите на задание только в одиночку.",
    [78676] = "Найдите глаз Бхосски в монастыре Алого ордена и доставьте его в тайник С у деревни Погребальных Костров. Идите на задание только в одиночку.",
    [79007] = "Надпись на обгоревшем клочке бумаги – ваша единственная подсказка.",
    [79008] = "Надпись на обгоревшем клочке бумаги – ваша единственная подсказка.",
    [79192] = "Вы отрываете записку от доски и читаете неразборчивые строки.",
    [79229] = "Найдите в Пустошах того, кому известно о разоренном лагере.",
    [79235] = "Найдите одного из мародеров из Пустошей.",
