    [97130] = "Достаньте идола древней империи Гурубаши из затонувшего города.",
    [97168] = "Если вы хотите помочь Элдруну Сокрушителю Бурь из Стальгорна, принесите ему азеротский алмаз и безупречный черный алмаз.",
    [97169] = "Используйте Магический кристалл в центре подвала Большого склепа в Некроситете. Это вызовет духов, с которыми вам придется сразиться. Когда вы их одолеете, появится рыцарь смерти Темный Губитель. Убейте его.$B$BПринесите голову Темного Губителя Элдруну Сокрушителю Бурь в Заброшенные пещеры Стальгорна.",
    [97173] = "Раздобудьте в логове Черночревов ритуальный тотем Черночревов.",
    [97174] = "Поговорите с Данитой Морр в Крепости Бандариона в Тирисфальских лесах.",
    [97175] = "Отправляйтесь в Оргриммар и получите кадило экзорцизма верховного жреца Заюса. Для этого вам придется пожертвовать 150 золотых.",
    [97176] = "С помощью кадила экзорцизма изгоните измученных духов из Долины Ужаса. Уничтожив 25 духов Долины Ужаса, вернитесь к Даните Морр в Крепость Бандариона в Тирисфальских лесах.",
    [97177] = "Верните кадило экзорцизма Даните Морр в Крепость Бандариона в Тирисфальских лесах.",
    [97178] = "Поговорите с Оттом на Мельнице Таррен в Предгорьях Хилсбрада.",
    [97179] = "Принесите Отту в Предгорья Хилсбрада 40 отрезов рунической ткани, 6 арканитовых слитков, 10 слез Артаса, 5 флаконов святой воды Стратхольма и 150 золотых.",
    [97180] = "Отнесите арканитовый чепрак Даните Морр в Крепость Бандариона, чтобы она его осмотрела.",
    [97182] = "Добудьте особый корм для призрачного коня. Такой корм может достать Натанос Гнилостень в Восточных Чумных землях.$B$BОтправляйтесь в Забытый Город в Фераласе и убейте Тендриса Криводрева. Так вы освободите Дух древнего коня. Чтобы успокоить его, накормите его особым кормом.$B$BНаконец, отдайте ему арканитовый чепрак и надейтесь, что он согласится дать необходимое благословение.",
    [97183] = "Вернитесь с Благословенным арканитовым чепраком к Даните Морр в Крепость Бандариона в Тирисфальских лесах.",
    [97184] = "Принесите азеротский алмаз и безупречный черный алмаз Даните Морр в Крепость Бандариона в Тирисфальских лесах.",
    [97185] = "Используйте Магический кристалл в центре подвала Большого склепа в Некроситете. Это вызовет духов, которых вам предстоит судить. Когда вы их одолеете, появится рыцарь смерти Темный Губитель. Убейте его и верните утраченную душу павшего боевого коня.$B$BОтдайте дух возмездия и благословенный зачарованный чепрак павшему боевому коню Темного Губителя.",
    [97186] = "Добудьте 20 обогащенных манных лепешек для Натаноса Гнилостеня в Восточных Чумных землях. Единственным поставщиком этих лепешек считается Серебряный Рассвет. Кроме того, вам придется заплатить Гнилостеню 50 золотых за потраченное время.",
    [97197] = "Раздобудьте в Глубинах Черной горы фрагмент Огненных Просторов для Алааны Штормовой Полет в Мулгоре.",
    [97198] = "Раздобудьте в логове Черночревов ритуальный тотем Черночревов.",
    [97243] = "Принесите факел спящего пламени Олариану Быстрая Вспышка в святилище пламени в Ветроягодных низинах.",
    [97244] = "Убейте жреца небес Фаладиэля в Ветроягодных низинах и заберите сердце Фаладиэля.",
    [97245] = "Отыщите дом Курамыы на Шен'дарском нагорье и одолейте духа в бою. Одержав победу, принесите его маску Олариану Быстрая Вспышка в Ветроягодных низинах.",
    [97250] = "Убейте солдат Альянса, хозяйничающих на границе Степей и Пылевых топей, а затем возвращайтесь к рубаке Логмару в Лагерь Таурахо.",
    [97257] = "Подождите, пока Олариан проводит ритуал у жаровни подношений, и следуйте его указаниям.",
    [97288] = "Принесите чудовищную голову мастеру аптекарю Фаранеллу в Подгород.",
    [97289] = "Принесите голову барона к телу Отмара в Подгород.",
    [97290] = "Расскажите мастеру аптекарю Фаранеллу в Подгороде о том, что вы узнали.",
    [97291] = "Добудьте ядовитую черепоганку у Шатенн Гризетт в Торговом квартале, жгуч-траву у наставника травничества и субстанцию агонии у торговца ядами в квартале Разбойников и принесите ингредиенты мастеру аптекарю Фаранеллу в Подгород.",
