    [97327] = "Проникните в логово Черночревов, соберите 5 |4кошель:кошеля:кошелей; Черночревов и принесите Эккалю в руины Эльдарата, что в Азшаре.",
    [97411] = "Добудьте 15 образцов яда из Силитуса и 20 золотых и отнесите их вместе со светоковаными наручами Моквару в Оргриммар.",
