    [98517] = "Поговорите с Сессарией Небесной Странницей или Аарнором Удар Шторма на острове Зефрис, чтобы продолжить обучение шамана.$B$BВы можете вернуться на Зефрис на неборезе, пришвартованном на Плато звездочетов к северо-западу от Громового Утеса в Мулгоре.",
    [98731] = "Найдите духа Великого Медведя на северо-западе Лунной поляны и усвойте все, что он расскажет вам о природе медведя. Когда уроки будут закончены, вернитесь к Дендриту Блеску Звезд в Ночную Гавань в Лунной поляне.",
    [98738] = "Найдите духа Великого Медведя на северо-западе Лунной поляны и усвойте все, что он расскажет вам о природе медведя. Когда уроки будут закончены, вернитесь к Дендриту Блеску Звезд в Ночную Гавань в Лунной поляне.",
    [98739] = "Поговорите с Дендритом.",
    [98830] = "Отнесите сломанную глефу Тортелдрина прародительнице Шен'дралар в Забытый город.",
    [99257] = "Убейте дряхлого защитника пилона, заберите его истощенное кристаллическое сердце и отнесите его историку Бираксасу в храм Шен'драласа.",
    [99258] = "Бросьте истощенное кристаллическое сердце в нестабильный разлом маны. Вернитесь к историку Бираксасу в храм Шен'драласа с доказательством успеха или неудачи.",
    [99260] = "Поговорите с Элаадрином Вечерняя Буря в Валанааре.",
    [99435] = "Сопроводите Реджинальда Винздора через весь Штормград. Защитите его!\\n\\nЕсли вам понадобится снова связаться с Реджинальдом Винздором, поговорите с оруженосцем Роу.",
    [99670] = "Вернитесь к Джереман в Колыбель Спокойствия.",
